    , 
    val `lifecycleMode`: LifecycleMode
    , 
    val `idleTimeoutSecs`: kotlin.ULong
    , 
    val `handshakeTimeoutSecs`: kotlin.ULong
    , 
    val `probeTimeoutSecs`: kotlin.ULong
    , 
    val `disabledTunnelIds`: List<kotlin.String>
    
){
    

    

    
    companion object
}

