/**
 * Engine errors, mapped from [`CoreError`] and config errors.
 */
sealed class EngineException: kotlin.Exception() {
    
    /**
     * The engine has not been started yet.
     */
    class NotStarted(
        ) : EngineException() {
        override val message
            get() = ""
    }
    
    /**
     * The engine is already started.
     */
    class AlreadyStarted(
        ) : EngineException() {
        override val message
            get() = ""
    }
    
    /**
     * No tunnel with this ID exists.
     */
    class TunnelNotFound(
        
        val v1: kotlin.String
        ) : EngineException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The TOML or `.conf` text failed to parse or validate.
     */
    class InvalidConfig(
        
        val v1: kotlin.String
        ) : EngineException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * A tunnel operation failed (activation, suspend, reload, ...).
     */
    class OperationFailed(
        
        val v1: kotlin.String
        ) : EngineException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * Requested feature is not implemented yet (e.g. TUN attach, Phase 2).
     */
    class NotSupported(
        
        val v1: kotlin.String
        ) : EngineException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EngineException> {
        override fun lift(error_buf: RustBuffer.ByValue): EngineException = FfiConverterTypeEngineError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeEngineError : FfiConverterRustBuffer<EngineException> {
    override fun read(buf: ByteBuffer): EngineException {
        

        return when(buf.getInt()) {
            1 -> EngineException.NotStarted()
            2 -> EngineException.AlreadyStarted()
            3 -> EngineException.TunnelNotFound(
                FfiConverterString.read(buf),
                )
            4 -> EngineException.InvalidConfig(
                FfiConverterString.read(buf),
                )
            5 -> EngineException.OperationFailed(
                FfiConverterString.read(buf),
                )
            6 -> EngineException.NotSupported(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EngineException): ULong {
        return when(value) {
            is EngineException.NotStarted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is EngineException.AlreadyStarted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is EngineException.TunnelNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is EngineException.InvalidConfig -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is EngineException.OperationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is EngineException.NotSupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: EngineException, buf: ByteBuffer) {
        when(value) {
            is EngineException.NotStarted -> {
                buf.putInt(1)
                Unit
            }
            is EngineException.AlreadyStarted -> {
                buf.putInt(2)
                Unit
            }
            is EngineException.TunnelNotFound -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is EngineException.InvalidConfig -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is EngineException.OperationFailed -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is EngineException.NotSupported -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



